/// Returns `true` when a terminal method is wire-invariant across profiles.
#[must_use]
pub fn is_invariant_terminal(wire_id: u32) -> bool {
    INVARIANT_TERMINALS.contains(&wire_id)
}

/// Returns the inner query of a transparent wrapper, if any.
fn wrapper_query(method: &Method) -> Option<&Method> {
    match method {
        Method::InvokeAfterMsg(value) => Some(value.query.as_ref()),
        Method::InvokeAfterMsgs(value) => Some(value.query.as_ref()),
        Method::InitConnection(value) => Some(value.query.as_ref()),
        Method::InvokeWithLayer(value) => Some(value.query.as_ref()),
        Method::InvokeWithoutUpdates(value) => Some(value.query.as_ref()),
        Method::InvokeWithMessagesRange(value) => Some(value.query.as_ref()),
        Method::InvokeWithTakeout(value) => Some(value.query.as_ref()),
        Method::InvokeWithBusinessConnection(value) => Some(value.query.as_ref()),
        Method::InvokeWithGooglePlayIntegrity(value) => Some(value.query.as_ref()),
        Method::InvokeWithApnsSecret(value) => Some(value.query.as_ref()),
        Method::InvokeWithReCaptcha(value) => Some(value.query.as_ref()),
        _ => None,
    }
}

/// Returns the layer selected by an `invokeWithLayer` wrapper.
fn wrapper_layer(method: &Method) -> Option<i32> {
    match method {
        Method::InvokeWithLayer(value) => Some(value.layer),
        _ => None,
    }
}

/// Builds immutable metadata for one transparent wrapper.
fn wrapper_metadata(method: &Method, profile: Option<Profile>, semantic: SemanticId) -> Wrapper {
    match method {
        Method::InvokeAfterMsg(value) => Wrapper {
            profile,
            semantic,
            wire_id: method.type_id(),
            kind: WrapperKind::InvokeAfterMsg,
            client: None,
            ordering: OrderingKey {
                msg_ids: vec![value.msg_id],
            },
        },
        Method::InvokeAfterMsgs(value) => Wrapper {
            profile,
            semantic,
            wire_id: method.type_id(),
            kind: WrapperKind::InvokeAfterMsgs,
            client: None,
            ordering: OrderingKey {
                msg_ids: value.msg_ids.clone(),
            },
        },
        Method::InitConnection(value) => Wrapper {
            profile,
            semantic,
            wire_id: method.type_id(),
            kind: WrapperKind::InitConnection,
            client: Some(ClientInfo {
                api_id: value.api_id,
                device_model: value.device_model.clone(),
                system_version: value.system_version.clone(),
                app_version: value.app_version.clone(),
                system_lang_code: value.system_lang_code.clone(),
                lang_pack: value.lang_pack.clone(),
                lang_code: value.lang_code.clone(),
            }),
            ordering: OrderingKey::default(),
        },
        Method::InvokeWithLayer(_) => Wrapper {
            profile,
            semantic,
            wire_id: method.type_id(),
            kind: WrapperKind::Layer,
            client: None,
            ordering: OrderingKey::default(),
        },
        _ => Wrapper {
            profile,
            semantic,
            wire_id: method.type_id(),
            kind: WrapperKind::Other,
            client: None,
            ordering: OrderingKey::default(),
        },
    }
}

/// Bounded admission limits.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Limits {
    /// Maximum wire bytes of the request.
    pub max_wire_bytes: usize,
    /// Maximum elements in a single vector.
    pub max_vector_elements: usize,
    /// Maximum aggregate vector elements.
    pub max_aggregate_elements: usize,
    /// Maximum nesting depth.
    pub max_depth: usize,
}

impl Default for Limits {
    fn default() -> Self {
        Self {
            max_wire_bytes: 16 * 1024 * 1024,
            max_vector_elements: 1 << 20,
            max_aggregate_elements: 1 << 20,
            max_depth: 64,
        }
    }
}

impl Limits {
    fn decode_limits(self) -> DecodeLimits {
        DecodeLimits {
            max_vector_elements: self.max_vector_elements,
            max_aggregate_elements: self.max_aggregate_elements,
            max_depth: self.max_depth,
        }
    }
}

/// An admission failure. Every variant fails closed.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AdmitError {
    /// The wire bytes could not be decoded.
    Decode(rtd_bin::Error),
    /// The selected layer is not enabled.
    UnsupportedLayer(i32),
    /// Two layer selectors disagreed.
    Conflict(i32, i32),
    /// A naked terminal is not wire-invariant.
    RequiresProfile(u32),
    /// The terminal has no route in the selected profile.
    UnsupportedTerminal(u32),
    /// The route exists but requires per-route codecs not emitted in this build.
    UnsupportedRoute(Route),
    /// A declared admission limit was exceeded.
    Limit {
        /// Limit name.
        name: &'static str,
        /// Measured value.
        value: usize,
    },
}

impl std::fmt::Display for AdmitError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            AdmitError::Decode(error) => write!(f, "decode error: {error}"),
            AdmitError::UnsupportedLayer(layer) => write!(f, "unsupported layer {layer}"),
            AdmitError::Conflict(a, b) => write!(f, "conflicting layer selectors {a} and {b}"),
            AdmitError::RequiresProfile(id) => {
                write!(f, "terminal {id:#010x} requires an exact profile")
            }
            AdmitError::UnsupportedTerminal(id) => {
                write!(
                    f,
                    "terminal {id:#010x} has no route in the selected profile"
                )
            }
            AdmitError::UnsupportedRoute(route) => {
                write!(
                    f,
                    "route {} is not emitted in this build",
                    route.mode.as_str()
                )
            }
            AdmitError::Limit { name, value } => {
                write!(f, "admission limit {name} exceeded ({value})")
            }
        }
    }
}

impl std::error::Error for AdmitError {}

impl From<rtd_bin::Error> for AdmitError {
    fn from(error: rtd_bin::Error) -> Self {
        AdmitError::Decode(error)
    }
}

/// The semantic kind of a transparently consumed RPC wrapper.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WrapperKind {
    /// `invokeWithLayer`, which selects an explicit profile.
    Layer,
    /// `initConnection`, which carries client and connection info.
    InitConnection,
    /// `invokeAfterMsg`, which depends on one prior message id.
    InvokeAfterMsg,
    /// `invokeAfterMsgs`, which depends on several prior message ids.
    InvokeAfterMsgs,
    /// Any other transparent wrapper.
    Other,
}

/// Client and connection info captured from an `initConnection` wrapper.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct ClientInfo {
    /// The client's declared API id.
    pub api_id: i32,
    /// The client device model string.
    pub device_model: String,
    /// The client operating-system version.
    pub system_version: String,
    /// The client application version.
    pub app_version: String,
    /// The client system language code.
    pub system_lang_code: String,
    /// The requested language pack.
    pub lang_pack: String,
    /// The requested language code.
    pub lang_code: String,
}

/// Prior-message dependencies declared by an `invokeAfter*` wrapper.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct OrderingKey {
    msg_ids: Vec<i64>,
}

impl OrderingKey {
    /// Returns `true` when the call depends on no prior message.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.msg_ids.is_empty()
    }

    /// Returns the number of prior message ids.
    #[must_use]
    pub fn len(&self) -> usize {
        self.msg_ids.len()
    }

    /// Returns the prior message ids in declaration order.
    #[must_use]
    pub fn as_slice(&self) -> &[i64] {
        &self.msg_ids
    }
}

/// Immutable metadata for one transparently consumed RPC wrapper.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Wrapper {
    profile: Option<Profile>,
    semantic: SemanticId,
    wire_id: u32,
    kind: WrapperKind,
    client: Option<ClientInfo>,
    ordering: OrderingKey,
}

impl Wrapper {
    /// Returns the profile in effect when the wrapper was parsed, if known.
    #[must_use]
    pub fn profile(&self) -> Option<Profile> {
        self.profile
    }

    /// Returns the stable semantic identity of the wrapper method.
    #[must_use]
    pub fn semantic(&self) -> SemanticId {
        self.semantic
    }

    /// Returns the wrapper terminal wire identifier.
    #[must_use]
    pub fn wire_id(&self) -> u32 {
        self.wire_id
    }

    /// Returns the wrapper kind.
    #[must_use]
    pub fn kind(&self) -> WrapperKind {
        self.kind
    }

    /// Returns the client and connection info of an `initConnection` wrapper.
    #[must_use]
    pub fn client(&self) -> Option<&ClientInfo> {
        self.client.as_ref()
    }

    /// Returns the prior-message ordering dependencies of this wrapper.
    #[must_use]
    pub fn ordering(&self) -> &OrderingKey {
        &self.ordering
    }
}

/// The comparable identity of an admitted call.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CallIdentity {
    semantic: SemanticId,
    wire_id: u32,
    ordering: OrderingKey,
}

impl CallIdentity {
    /// Returns the stable semantic identity of the call.
    #[must_use]
    pub fn semantic(&self) -> SemanticId {
        self.semantic
    }

    /// Returns the admitted terminal wire identifier.
    #[must_use]
    pub fn wire_id(&self) -> u32 {
        self.wire_id
    }

    /// Returns the accumulated invoke-after ordering key of the call.
    #[must_use]
    pub fn ordering(&self) -> &OrderingKey {
        &self.ordering
    }
}

/// An admitted, exact-profile request.
#[derive(Debug, Clone)]
pub struct Admission {
    /// The effective profile, or `None` for a wire-invariant terminal.
    pub effective_profile: Option<Profile>,
    /// Explicit profile evidence from a wrapper, if any.
    pub explicit_profile: Option<Profile>,
    /// The terminal wire identifier.
    pub wire_id: u32,
    /// The terminal semantic identity.
    pub semantic: SemanticId,
    /// The decoded canonical request.
    pub request: Method,
    /// The original wire size in bytes.
    pub wire_size: usize,
    /// SHA-256 of the original wire bytes.
    pub wire_digest: [u8; 32],
    /// The transparent wrappers consumed around the terminal, outermost first.
    pub wrappers: Vec<Wrapper>,
    /// The admitted call identity.
    pub call_identity: CallIdentity,
}

/// A view over an admitted request: explicit and effective profile plus the
/// ordered wrapper metadata.
#[derive(Debug, Clone, Copy)]
pub struct AdmissionView<'a> {
    admission: &'a Admission,
}

impl<'a> AdmissionView<'a> {
    /// Returns the explicit profile evidence from a wrapper, if any.
    #[must_use]
    pub fn explicit_profile(&self) -> Option<Profile> {
        self.admission.explicit_profile
    }

    /// Returns the effective profile, or `None` for a wire-invariant terminal.
    #[must_use]
    pub fn effective_profile(&self) -> Option<Profile> {
        self.admission.effective_profile
    }

    /// Returns the wrappers consumed around the terminal, outermost first.
    #[must_use]
    pub fn wrappers(&self) -> &'a [Wrapper] {
        &self.admission.wrappers
    }

    /// Returns the number of wrappers consumed around the terminal.
    #[must_use]
    pub fn wrapper_count(&self) -> usize {
        self.admission.wrappers.len()
    }

    /// Returns one wrapper by index.
    #[must_use]
    pub fn wrapper(&self, index: usize) -> Option<&'a Wrapper> {
        self.admission.wrappers.get(index)
    }

    /// Returns the admitted call identity.
    #[must_use]
    pub fn call_identity(&self) -> &'a CallIdentity {
        &self.admission.call_identity
    }
}

impl Admission {
    /// Returns a view over the explicit/effective profile and wrapper metadata.
    #[must_use]
    pub fn view(&self) -> AdmissionView<'_> {
        AdmissionView { admission: self }
    }

    /// Returns the wrappers consumed around the terminal, outermost first.
    #[must_use]
    pub fn wrappers(&self) -> &[Wrapper] {
        &self.wrappers
    }

    /// Returns the admitted call identity.
    #[must_use]
    pub fn call_identity(&self) -> &CallIdentity {
        &self.call_identity
    }

    /// Returns the accumulated invoke-after ordering key of the call.
    #[must_use]
    pub fn ordering(&self) -> &OrderingKey {
        &self.call_identity.ordering
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AdmitMode {
    Frozen,
    Default,
    Unprofiled,
}

fn admit_impl(
    mode: AdmitMode,
    caller: Option<Profile>,
    body: &[u8],
    limits: Limits,
) -> Result<Admission, AdmitError> {
    if body.len() > limits.max_wire_bytes {
        return Err(AdmitError::Limit {
            name: "max_wire_bytes",
            value: body.len(),
        });
    }
    let mut decoder = Decoder::new(body, limits.decode_limits());
    let decoded = Method::decode(&mut decoder)?;
    if !decoder.is_empty() {
        return Err(AdmitError::Limit {
            name: "trailing_bytes",
            value: decoder.remaining(),
        });
    }

    let mut explicit: Option<i32> = None;
    let mut wrappers: Vec<Wrapper> = Vec::new();
    let mut ordering: Vec<i64> = Vec::new();
    let mut wrapper_profile = match mode {
        AdmitMode::Unprofiled => None,
        AdmitMode::Frozen | AdmitMode::Default => caller,
    };
    let mut current: &Method = &decoded;
    while let Some(inner) = wrapper_query(current) {
        let wire_id = current.type_id();
        let semantic = semantic_for_wire_id(Profile::new(CANONICAL_LAYER), wire_id)
            .ok_or(AdmitError::UnsupportedTerminal(wire_id))?;
        let wrapper = wrapper_metadata(current, wrapper_profile, semantic);
        ordering.extend_from_slice(wrapper.ordering().as_slice());
        if let Some(layer) = wrapper_layer(current) {
            match explicit {
                None => explicit = Some(layer),
                Some(previous) if previous != layer => {
                    return Err(AdmitError::Conflict(previous, layer));
                }
                Some(_) => {}
            }
            wrapper_profile = Some(Profile::new(layer));
        }
        wrappers.push(wrapper);
        current = inner;
    }
    let terminal = current;
    let terminal_id = terminal.type_id();

    let effective = match mode {
        AdmitMode::Frozen => {
            let caller = caller.expect("frozen admission requires a profile");
            if let Some(layer) = explicit
                && layer != caller.layer
            {
                return Err(AdmitError::Conflict(caller.layer, layer));
            }
            Some(caller)
        }
        AdmitMode::Default => match explicit {
            Some(layer) => Some(Profile::new(layer)),
            None => caller,
        },
        AdmitMode::Unprofiled => explicit.map(Profile::new),
    };

    let mut admitted_profile: Option<Profile> = None;
    if let Some(profile) = effective {
        if !profile.is_supported() {
            return Err(AdmitError::UnsupportedLayer(profile.layer));
        }
        let route = lookup_route(profile, terminal_id)
            .ok_or(AdmitError::UnsupportedTerminal(terminal_id))?;
        if route.mode != RouteMode::Direct {
            return Err(AdmitError::UnsupportedRoute(route));
        }
        admitted_profile = Some(profile);
    } else if !is_invariant_terminal(terminal_id) {
        return Err(AdmitError::RequiresProfile(terminal_id));
    }

    let semantic = match admitted_profile {
        Some(profile) => semantic_for_wire_id(profile, terminal_id)
            .ok_or(AdmitError::UnsupportedTerminal(terminal_id))?,
        None => semantic_for_invariant(terminal_id)
            .ok_or(AdmitError::UnsupportedTerminal(terminal_id))?,
    };

    let call_identity = CallIdentity {
        semantic,
        wire_id: terminal_id,
        ordering: OrderingKey { msg_ids: ordering },
    };
    let mut wire_digest = [0u8; 32];
    wire_digest.copy_from_slice(&sha256(body));
    Ok(Admission {
        effective_profile: admitted_profile,
        explicit_profile: explicit.map(Profile::new),
        wire_id: terminal_id,
        semantic,
        request: decoded,
        wire_size: body.len(),
        wire_digest,
        wrappers,
        call_identity,
    })
}

/// Finds the semantic identity of a wire-invariant terminal.
fn semantic_for_invariant(wire_id: u32) -> Option<SemanticId> {
    for layer in PROFILES {
        if let Some(semantic) = ROUTES
            .iter()
            .find(|route| route.profile == *layer && route.wire_id == wire_id)
            .map(|route| route.semantic)
        {
            return Some(semantic);
        }
    }
    None
}

/// Admits a request against a frozen, exact profile.
///
/// # Errors
///
/// Returns an [`AdmitError`] when the request is malformed, selects a different
/// layer, exceeds a limit, or has no route.
pub fn admit(profile: Profile, body: &[u8]) -> Result<Admission, AdmitError> {
    admit_impl(AdmitMode::Frozen, Some(profile), body, Limits::default())
}

/// Admits a request against a frozen profile with explicit limits.
///
/// # Errors
///
/// As [`admit`].
pub fn admit_with_limits(
    profile: Profile,
    body: &[u8],
    limits: Limits,
) -> Result<Admission, AdmitError> {
    admit_impl(AdmitMode::Frozen, Some(profile), body, limits)
}

/// Admits a request, letting the first selector replace the inherited default.
///
/// # Errors
///
/// As [`admit`].
pub fn admit_default(profile: Profile, body: &[u8]) -> Result<Admission, AdmitError> {
    admit_impl(AdmitMode::Default, Some(profile), body, Limits::default())
}

/// Admits a request with default inheritance and explicit limits.
///
/// # Errors
///
/// As [`admit`].
pub fn admit_default_with_limits(
    profile: Profile,
    body: &[u8],
    limits: Limits,
) -> Result<Admission, AdmitError> {
    admit_impl(AdmitMode::Default, Some(profile), body, limits)
}

/// Admits a request that carries no caller profile.
///
/// # Errors
///
/// As [`admit`].
pub fn admit_unprofiled(body: &[u8]) -> Result<Admission, AdmitError> {
    admit_impl(AdmitMode::Unprofiled, None, body, Limits::default())
}

/// Admits an unprofiled request with explicit limits.
///
/// # Errors
///
/// As [`admit`].
pub fn admit_unprofiled_with_limits(body: &[u8], limits: Limits) -> Result<Admission, AdmitError> {
    admit_impl(AdmitMode::Unprofiled, None, body, limits)
}

/// A projection or encoding failure. Every variant fails closed.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ProjectionError {
    /// The target profile is not enabled.
    UnsupportedProfile(i32),
    /// The value's constructor has no route in the target profile.
    Unrepresentable {
        /// Target layer.
        layer: i32,
        /// Constructor wire identifier.
        wire_id: u32,
    },
    /// The route requires per-route codecs not emitted in this build.
    RouteNotEmitted(Route),
}

impl std::fmt::Display for ProjectionError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ProjectionError::UnsupportedProfile(layer) => {
                write!(f, "unsupported profile layer {layer}")
            }
            ProjectionError::Unrepresentable { layer, wire_id } => write!(
                f,
                "value {wire_id:#010x} is not representable in layer {layer}"
            ),
            ProjectionError::RouteNotEmitted(route) => {
                write!(
                    f,
                    "route {} is not emitted in this build",
                    route.mode.as_str()
                )
            }
        }
    }
}

impl std::error::Error for ProjectionError {}

/// A canonical value frozen once for per-profile encoding.
#[derive(Debug, Clone)]
pub struct FrozenObject {
    value: Object,
    type_id: u32,
}

impl FrozenObject {
    /// Freezes a canonical value, validating representability.
    ///
    /// # Errors
    ///
    /// Returns an error when the value's constructor is not part of the
    /// canonical route table.
    pub fn freeze(value: Object) -> Result<Self, ProjectionError> {
        let type_id = value.type_id();
        let representable = ROUTES
            .iter()
            .any(|route| route.profile == CANONICAL_LAYER && route.wire_id == type_id);
        if !representable {
            return Err(ProjectionError::Unrepresentable {
                layer: CANONICAL_LAYER,
                wire_id: type_id,
            });
        }
        Ok(Self { value, type_id })
    }

    /// Returns the canonical value.
    #[must_use]
    pub fn canonical(&self) -> &Object {
        &self.value
    }

    /// Returns the constructor wire identifier.
    #[must_use]
    pub const fn type_id(&self) -> u32 {
        self.type_id
    }

    /// Encodes the value for an exact profile, failing closed.
    ///
    /// # Errors
    ///
    /// Returns an error when the profile is unsupported or cannot represent the
    /// value; it never falls back to the canonical encoding.
    pub fn encode(&self, profile: Profile, out: &mut Writer) -> Result<(), ProjectionError> {
        let route =
            lookup_route(profile, self.type_id).ok_or(ProjectionError::Unrepresentable {
                layer: profile.layer,
                wire_id: self.type_id,
            })?;
        encode_route(route, &self.value, out)
    }
}

/// Encodes a canonical value according to an exact route.
///
/// # Errors
///
/// Returns an error for non-direct routes, which require per-route codecs.
pub fn encode_route(route: Route, value: &Object, out: &mut Writer) -> Result<(), ProjectionError> {
    match route.mode {
        RouteMode::Direct => {
            value.encode(out);
            Ok(())
        }
        _ => Err(ProjectionError::RouteNotEmitted(route)),
    }
}

/// Decodes a boxed object for an exact profile, failing closed.
///
/// # Errors
///
/// Returns an error when the profile is unsupported, a limit is exceeded,
/// trailing bytes remain, or the value has no route in the profile.
pub fn decode_object(profile: Profile, bytes: &[u8], limits: Limits) -> Result<Object, AdmitError> {
    if !profile.is_supported() {
        return Err(AdmitError::UnsupportedLayer(profile.layer));
    }
    if bytes.len() > limits.max_wire_bytes {
        return Err(AdmitError::Limit {
            name: "max_wire_bytes",
            value: bytes.len(),
        });
    }
    let mut decoder = Decoder::new(bytes, limits.decode_limits());
    let value = Object::decode(&mut decoder)?;
    if !decoder.is_empty() {
        return Err(AdmitError::Limit {
            name: "trailing_bytes",
            value: decoder.remaining(),
        });
    }
    let route = lookup_route(profile, value.type_id())
        .ok_or(AdmitError::UnsupportedTerminal(value.type_id()))?;
    if route.mode != RouteMode::Direct {
        return Err(AdmitError::UnsupportedRoute(route));
    }
    Ok(value)
}

/// A dispatch failure.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum DispatchError {
    /// No handler is registered for the method.
    NoHandler(SemanticId),
    /// The handler rejected the call.
    Handler(String),
    /// The result could not be encoded for the effective profile.
    Projection(ProjectionError),
    /// A naked invariant terminal cannot produce a frozen profile value.
    Value(ProjectionError),
}

impl std::fmt::Display for DispatchError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            DispatchError::NoHandler(id) => write!(f, "no handler for semantic {:016x}", id.0),
            DispatchError::Handler(message) => write!(f, "handler error: {message}"),
            DispatchError::Projection(error) => write!(f, "projection error: {error}"),
            DispatchError::Value(error) => write!(f, "value error: {error}"),
        }
    }
}

impl std::error::Error for DispatchError {}

/// A semantic handler.
pub trait Handler {
    /// Handles an admitted request and returns a canonical result.
    ///
    /// # Errors
    ///
    /// Returns a message when the call cannot be served.
    fn handle(&self, admission: &Admission) -> Result<Object, String>;
}

impl<F> Handler for F
where
    F: Fn(&Admission) -> Result<Object, String>,
{
    fn handle(&self, admission: &Admission) -> Result<Object, String> {
        self(admission)
    }
}

/// The result of dispatching an admitted call, bound to its call identity.
#[derive(Debug, Clone)]
pub struct DispatchResult {
    identity: CallIdentity,
    value: FrozenObject,
}

impl DispatchResult {
    /// Returns the admitted call identity that produced this result.
    #[must_use]
    pub fn identity(&self) -> &CallIdentity {
        &self.identity
    }

    /// Returns the frozen canonical result value.
    #[must_use]
    pub fn value(&self) -> &FrozenObject {
        &self.value
    }

    /// Consumes the result, returning the frozen canonical value.
    #[must_use]
    pub fn into_value(self) -> FrozenObject {
        self.value
    }

    /// Encodes the result for an exact profile, failing closed.
    ///
    /// # Errors
    ///
    /// As [`FrozenObject::encode`].
    pub fn encode(&self, profile: Profile, out: &mut Writer) -> Result<(), ProjectionError> {
        self.value.encode(profile, out)
    }
}

/// A dispatcher keyed by stable semantic identity.
#[derive(Default)]
pub struct Dispatcher {
    handlers: std::collections::HashMap<u64, Box<dyn Handler>>,
}

impl Dispatcher {
    /// Creates an empty dispatcher.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Registers a handler, replacing any previous handler for the identity.
    pub fn register<H: Handler + 'static>(&mut self, semantic: SemanticId, handler: H) {
        self.handlers.insert(semantic.0, Box::new(handler));
    }

    /// Dispatches an admitted request and freezes the canonical result.
    ///
    /// # Errors
    ///
    /// Returns an error when no handler is registered, the handler fails, or
    /// the result cannot be frozen.
    pub fn dispatch(&self, admission: &Admission) -> Result<DispatchResult, DispatchError> {
        let handler = self
            .handlers
            .get(&admission.semantic.0)
            .ok_or(DispatchError::NoHandler(admission.semantic))?;
        let value = handler.handle(admission).map_err(DispatchError::Handler)?;
        let value = FrozenObject::freeze(value).map_err(DispatchError::Value)?;
        Ok(DispatchResult {
            identity: admission.call_identity.clone(),
            value,
        })
    }
}

/// Returns the raw SHA-256 of `bytes`.
fn sha256(bytes: &[u8]) -> [u8; 32] {
    use sha2::{Digest, Sha256};
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    let mut out = [0u8; 32];
    out.copy_from_slice(&hasher.finalize());
    out
}

#[cfg(test)]
mod generated_tests {
    use super::*;

    #[test]
    fn profile_resolution_is_fail_closed() {
        assert!(resolve_profile(CANONICAL_LAYER).is_some());
        assert!(resolve_profile(CANONICAL_LAYER + 1).is_none());
        assert_eq!(
            resolve_profile(CANONICAL_LAYER).unwrap().layer(),
            CANONICAL_LAYER
        );
    }

    #[test]
    fn routes_are_loaded() {
        assert!(!PROFILES.is_empty());
        for route in ROUTES {
            assert!(PROFILES.contains(&route.profile));
            assert!(lookup_route(Profile::new(route.profile), route.wire_id).is_some());
        }
    }
}
